from typing import Annotated, Any, Literal, Union
from typing_extensions import get_origin, get_args, Tag, Discriminator
from pydantic import BaseModel

class Pie(BaseModel):
    time_to_cook: int
    num_ingredients: int

class ApplePie(Pie):
    fruit: Literal["apple"] = "apple"

class PumpkinPie(Pie):
    filling: Literal["pumpkin"] = "pumpkin"

def get_discriminator_value(v: Any) -> str:
    if isinstance(v, dict):
        return v.get("fruit", v.get("filling"))
    return getattr(v, "fruit", getattr(v, "filling", None))

Dessert = Annotated[
    Annotated[ApplePie, Tag("apple")] | Annotated[PumpkinPie, Tag("pumpkin")],
    Discriminator(get_discriminator_value),
]
print("origin:", get_origin(Dessert))
print("args:", get_args(Dessert))
inner = get_args(Dessert)[0]
print("inner origin:", get_origin(inner), get_origin(inner) is Annotated)
from fastapi._compat import field_annotation_is_scalar, field_annotation_is_complex
print("scalar?", field_annotation_is_scalar(inner))
print("complex?", field_annotation_is_complex(inner))
EOF"}

